{"version":3,"sources":["..\\scss\\publicationSlug.scss","publicationSlug.css","..\\scss\\_mixins.scss","..\\scss\\_variables.scss"],"names":[],"mappings":"AAGA;EACE,gBAAA;ACFF;;ADKA;EENE,uCAAA;EACA,gBFMoC;EELpC,kBAAA;EACA,YCHa;EDIb,eFG8B;EAC9B,mBAAA;ACEF;;ADCA;EEXE,uCAAA;EACA,gBFWoC;EEVpC,kBAAA;EACA,YCHa;EDIb,eFQ8B;EAC9B,mBAAA;ACMF;;ADHA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;EACA,aAAA;EACA,kBAAA;EACA,uBAAA;ACMF;;ADFE;EACE,kBAAA;EACA,WAAA;EACA,YAAA;EACA,oBAAA;KAAA,iBAAA;EACA,0BAAA;KAAA,uBAAA;ACKJ;;ADDA;EEnCE,uCAAA;EACA,gBFmCoC;EElCpC,kBAAA;EACA,YCHa;EDIb,eFgC8B;ACQhC;ADPE;EErCA,uCAAA;EACA,gBFqCsC;EEpCtC,kBAAA;EACA,YCHa;EDIb,eFkCgC;ACalC;ADVE;EEzCA,uCAAA;EACA,gBFyCsC;EExCtC,kBAAA;EACA,YCHa;EDIb,eFsCgC;ACgBlC;ADbE;EACE,aAAA;EACA,sBAAA;EACA,QAAA;ACeJ;;ADXA;EACE,gBAAA;EErDA,uCAAA;EACA,gBFqDoC;EEpDpC,kBAAA;EACA,YCHa;EDIb,eFkD8B;ACkBhC","file":"publicationSlug.css","sourcesContent":["@import \"./variables\";\r\n@import \"./mixins\";\r\n\r\n.section_publications {\r\n  margin-top: 20px;\r\n}\r\n\r\n.publication_text_title {\r\n  @include fonts($defaultColor, 24px, 600);\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.publication_data {\r\n  @include fonts($defaultColor, 14px, 400);\r\n  margin-bottom: 10px;\r\n}\r\n\r\n.publication_link_wrap {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 20px;\r\n  padding: 10px;\r\n  border-radius: 5px;\r\n  border: 1px solid $defaultColor;\r\n}\r\n\r\n.publication_img {\r\n  & img {\r\n    border-radius: 5px;\r\n    width: 100%;\r\n    height: 100%;\r\n    object-fit: cover;\r\n    object-position: center;\r\n  }\r\n}\r\n\r\n.publication_text {\r\n  @include fonts($defaultColor, 14px, 400);\r\n  & p, li {\r\n    @include fonts($defaultColor, 14px, 400);\r\n  }\r\n\r\n  :where(h1,h2,h3,h4,h5,h6) {\r\n    @include fonts($defaultColor, 18px, 600);\r\n  }\r\n\r\n  & ul,ol {\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 5px;\r\n  }\r\n}\r\n\r\n.publication_views {\r\n  margin-top: 10px;\r\n  @include fonts($defaultColor, 14px, 400);\r\n}",".section_publications {\n  margin-top: 20px;\n}\n\n.publication_text_title {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: black;\n  font-size: 24px;\n  margin-bottom: 20px;\n}\n\n.publication_data {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  margin-bottom: 10px;\n}\n\n.publication_link_wrap {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n  padding: 10px;\n  border-radius: 5px;\n  border: 1px solid black;\n}\n\n.publication_img img {\n  border-radius: 5px;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n\n.publication_text {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.publication_text p, .publication_text li {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.publication_text :where(h1, h2, h3, h4, h5, h6) {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: black;\n  font-size: 18px;\n}\n.publication_text ul, .publication_text ol {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n\n.publication_views {\n  margin-top: 10px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}","@mixin fonts($color,$size,$weight) {\r\n  font-family: 'Trebuchet MS', sans-serif;\r\n  font-weight: $weight;\r\n  font-style: normal;\r\n  color: $color;\r\n  font-size: $size;\r\n}","$mainColor: #3077a0;\r\n$defaultColor: black;\r\n$colorHover: red;\r\n$headerTopBorder: #bdd4e2;\r\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\r\n$gray: #D4D4D4;\r\n$vipBg: #ff6163;\r\n$activeItem: #FFFFCA;\r\n$userSearchBg: #CFE6FE;\r\n$asideLinksColor: #307792;\r\n$asideExitColor: rgb(0, 128, 0);"]}inksColor: #307792;\r\n$asideExitColor: rgb(0, 128, 0);"]}